#!/usr/bin/env python3
"""Grade the check-gate `ranges` task: run the pristine visible tests plus
hidden tests derived from the task's specification against a copy of the
workspace whose own tests/ directory is replaced. Editing the workspace's tests
changes nothing here. The last output line is `<failed> failed, <passed> passed`."""
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

TEST_FILES = {'tests/__init__.py': '# Unit tests.\n', 'tests/run.py': '"""Run the unit tests under tests/ and report them like pytest\'s summary:\nthe failure details first, then one `FAILED <test> - <reason>` line per\nfailing test and a count line. Exit status 1 when anything failed."""\nimport os\nimport sys\nimport unittest\n\n\ndef main():\n    here = os.path.dirname(os.path.abspath(__file__))\n    root = os.path.dirname(here)\n    sys.path.insert(0, root)\n    suite = unittest.defaultTestLoader.discover(here, pattern="test_*.py", top_level_dir=root)\n    result = unittest.TestResult()\n    suite.run(result)\n    failed = result.failures + result.errors\n    for test, trace in failed:\n        print("_" * 12 + " " + test.id() + " " + "_" * 12)\n        print(trace.rstrip())\n        print()\n    failing_methods = set()\n    for test, trace in failed:\n        case = getattr(test, "test_case", test)\n        failing_methods.add(case.id())\n        parts = case.id().rsplit(".", 2)\n        if len(parts) == 3:\n            module, cls, method = parts\n            name = "%s.py::%s::%s" % (module.replace(".", "/"), cls, method)\n        else:\n            name = case.id()\n        if case is not test:\n            name += " " + test._subDescription()\n        lines = trace.strip().splitlines()\n        reason = lines[-1] if lines else ""\n        print("FAILED %s - %s" % (name, reason))\n    print("%d failed, %d passed" % (len(failing_methods), result.testsRun - len(failing_methods)))\n    return 1 if failed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_basic.py': 'import unittest\n\nfrom ranges import max_satisfying, satisfies\n\nclass RangesBasicTest(unittest.TestCase):\n    def test_exact_match(self):\n        self.assertIs(satisfies(\'1.2.3\', \'1.2.3\'), True)\n\n    def test_exact_mismatch(self):\n        self.assertIs(satisfies(\'1.2.4\', \'1.2.3\'), False)\n\n    def test_and_set_inside(self):\n        self.assertIs(satisfies(\'1.5.0\', \'>=1.2.0 <2.0.0\'), True)\n\n    def test_and_set_upper_bound(self):\n        self.assertIs(satisfies(\'2.0.0\', \'>=1.2.0 <2.0.0\'), False)\n\n    def test_or_sets(self):\n        self.assertIs(satisfies(\'3.1.0\', \'1.x || >=3.0.0\'), True)\n\n    def test_star_matches_releases(self):\n        self.assertIs(satisfies(\'0.0.1\', \'*\'), True)\n\n    def test_empty_range_matches_releases(self):\n        self.assertIs(satisfies(\'5.0.0\', \'\'), True)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_caret_tilde.py': 'import unittest\n\nfrom ranges import max_satisfying, satisfies\n\nclass RangesCaretTildeTest(unittest.TestCase):\n    def test_caret_minor_bump_allowed(self):\n        self.assertIs(satisfies(\'1.9.0\', \'^1.2.3\'), True)\n\n    def test_caret_major_excluded(self):\n        self.assertIs(satisfies(\'2.0.0\', \'^1.2.3\'), False)\n\n    def test_caret_zero_major(self):\n        self.assertIs(satisfies(\'0.2.9\', \'^0.2.3\'), True)\n\n    def test_caret_zero_major_minor_bump_excluded(self):\n        self.assertIs(satisfies(\'0.3.0\', \'^0.2.3\'), False)\n\n    def test_caret_zero_zero(self):\n        self.assertIs(satisfies(\'0.0.4\', \'^0.0.3\'), False)\n\n    def test_tilde_patch_allowed(self):\n        self.assertIs(satisfies(\'1.2.9\', \'~1.2.3\'), True)\n\n    def test_tilde_minor_excluded(self):\n        self.assertIs(satisfies(\'1.3.0\', \'~1.2.3\'), False)\n\n    def test_tilde_major_only(self):\n        self.assertIs(satisfies(\'1.9.0\', \'~1\'), True)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_partials.py': 'import unittest\n\nfrom ranges import max_satisfying, satisfies\n\nclass RangesPartialsTest(unittest.TestCase):\n    def test_x_minor(self):\n        self.assertIs(satisfies(\'1.4.0\', \'1.x\'), True)\n\n    def test_x_minor_next_major(self):\n        self.assertIs(satisfies(\'2.0.0\', \'1.x\'), False)\n\n    def test_star_patch(self):\n        self.assertIs(satisfies(\'1.2.9\', \'1.2.*\'), True)\n\n    def test_greater_than_partial(self):\n        self.assertIs(satisfies(\'1.2.9\', \'>1.2\'), False)\n\n    def test_greater_than_partial_next(self):\n        self.assertIs(satisfies(\'1.3.0\', \'>1.2\'), True)\n\n    def test_less_equal_partial(self):\n        self.assertIs(satisfies(\'1.2.9\', \'<=1.2\'), True)\n\n    def test_less_equal_partial_next(self):\n        self.assertIs(satisfies(\'1.3.0\', \'<=1.2\'), False)\n\n    def test_hyphen_inclusive(self):\n        self.assertIs(satisfies(\'2.3.4\', \'1.2.3 - 2.3.4\'), True)\n\n    def test_hyphen_above(self):\n        self.assertIs(satisfies(\'2.3.5\', \'1.2.3 - 2.3.4\'), False)\n\n    def test_hyphen_partial_upper(self):\n        self.assertIs(satisfies(\'2.3.9\', \'1.2.3 - 2.3\'), True)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_prerelease.py': 'import unittest\n\nfrom ranges import max_satisfying, satisfies\n\nclass RangesPrereleaseTest(unittest.TestCase):\n    def test_prerelease_excluded_by_default(self):\n        self.assertIs(satisfies(\'1.2.4-beta\', \'>=1.2.3\'), False)\n\n    def test_prerelease_on_same_tuple(self):\n        self.assertIs(satisfies(\'1.2.3-rc.1\', \'>=1.2.3-beta.2 <1.3.0\'), True)\n\n    def test_prerelease_below_bound(self):\n        self.assertIs(satisfies(\'1.2.3-alpha\', \'>=1.2.3-beta.2\'), False)\n\n    def test_prerelease_numeric_order(self):\n        self.assertIs(satisfies(\'1.0.0-beta.11\', \'>1.0.0-beta.2\'), True)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_api.py': 'import unittest\n\nfrom ranges import max_satisfying, satisfies\n\nclass RangesApiTest(unittest.TestCase):\n    def test_invalid_version(self):\n        with self.assertRaises(ValueError):\n            satisfies(\'1.2\', \'1.x\')\n\n    def test_invalid_range(self):\n        with self.assertRaises(ValueError):\n            satisfies(\'1.2.3\', \'>=1.2.3 ||| 2\')\n\n    def test_unsupported_operator(self):\n        with self.assertRaises(ValueError):\n            satisfies(\'1.2.3\', \'~>1.2\')\n\n    def test_leading_zero_version(self):\n        with self.assertRaises(ValueError):\n            satisfies(\'01.2.3\', \'*\')\n\n    def test_max_satisfying(self):\n        self.assertEqual(max_satisfying([\'1.2.3\', \'1.2.4\', \'1.3.0\', \'2.0.0\'], \'~1.2.0\'), \'1.2.4\')\n\n    def test_max_satisfying_none(self):\n        self.assertEqual(max_satisfying([\'1.2.3\', \'1.2.4\'], \'^2.0.0\'), None)\n\n    def test_max_satisfying_skips_invalid(self):\n        self.assertEqual(max_satisfying([\'1.2.3\', \'banana\', \'1.5.0\'], \'^1.0.0\'), \'1.5.0\')\n\n    def test_max_satisfying_skips_prerelease(self):\n        self.assertEqual(max_satisfying([\'1.2.3\', \'1.3.0-beta\'], \'^1.2.3\'), \'1.2.3\')\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tests/test_hidden_ranges.py': 'import unittest\n\nfrom ranges import max_satisfying, satisfies\n\nclass RangesHiddenTest(unittest.TestCase):\n    def test_caret_zero_zero_partial(self):\n        self.assertIs(satisfies(\'0.0.9\', \'^0.0\'), True)\n\n    def test_caret_zero_zero_partial_out(self):\n        self.assertIs(satisfies(\'0.1.0\', \'^0.0\'), False)\n\n    def test_caret_zero_only(self):\n        self.assertIs(satisfies(\'0.9.9\', \'^0\'), True)\n\n    def test_caret_partial(self):\n        self.assertIs(satisfies(\'1.9.0\', \'^1.2\'), True)\n\n    def test_tilde_partial_out(self):\n        self.assertIs(satisfies(\'1.3.0\', \'~1.2\'), False)\n\n    def test_tilde_prerelease_lower(self):\n        self.assertIs(satisfies(\'1.2.3-beta.4\', \'~1.2.3-beta.2\'), True)\n\n    def test_tilde_prerelease_other_tuple(self):\n        self.assertIs(satisfies(\'1.2.4-beta\', \'~1.2.3-beta.2\'), False)\n\n    def test_caret_prerelease_lower(self):\n        self.assertIs(satisfies(\'1.2.3-beta.3\', \'^1.2.3-beta.2\'), True)\n\n    def test_caret_prerelease_release(self):\n        self.assertIs(satisfies(\'1.2.3\', \'^1.2.3-beta.2\'), True)\n\n    def test_caret_prerelease_next_minor(self):\n        self.assertIs(satisfies(\'1.3.0-beta\', \'^1.2.3-beta.2\'), False)\n\n    def test_greater_major_partial(self):\n        self.assertIs(satisfies(\'2.0.0\', \'>1\'), True)\n\n    def test_greater_major_partial_out(self):\n        self.assertIs(satisfies(\'1.9.9\', \'>1\'), False)\n\n    def test_less_partial_excludes_prerelease(self):\n        self.assertIs(satisfies(\'1.2.0-beta\', \'<1.2\'), False)\n\n    def test_less_partial(self):\n        self.assertIs(satisfies(\'1.1.9\', \'<1.2\'), True)\n\n    def test_hyphen_partial_lower(self):\n        self.assertIs(satisfies(\'1.2.0\', \'1.2 - 2.3.4\'), True)\n\n    def test_hyphen_major_upper(self):\n        self.assertIs(satisfies(\'2.9.9\', \'1.2.3 - 2\'), True)\n\n    def test_hyphen_major_upper_out(self):\n        self.assertIs(satisfies(\'3.0.0\', \'1.2.3 - 2\'), False)\n\n    def test_whitespace_after_operator(self):\n        self.assertIs(satisfies(\'1.9.0\', \'>= 1.2.3 < 2\'), True)\n\n    def test_prerelease_in_second_set(self):\n        self.assertIs(satisfies(\'2.0.0-beta\', \'1.x || >=2.0.0-alpha\'), True)\n\n    def test_numeric_prerelease_below_alpha(self):\n        self.assertIs(satisfies(\'1.0.0-1\', \'>=1.0.0-alpha\'), False)\n\n    def test_wildcard_then_number(self):\n        with self.assertRaises(ValueError):\n            satisfies(\'1.2.3\', \'1.x.3\')\n\n    def test_prerelease_on_partial(self):\n        with self.assertRaises(ValueError):\n            satisfies(\'1.2.3\', \'1.2-beta\')\n\n    def test_equals_partial(self):\n        self.assertIs(satisfies(\'1.2.5\', \'=1.2\'), True)\n\n    def test_capital_x(self):\n        self.assertIs(satisfies(\'7.0.0\', \'X\'), True)\n\n    def test_max_prerelease_range(self):\n        self.assertEqual(max_satisfying([\'2.0.0-alpha\', \'2.0.0-beta\', \'1.9.0\'], \'>=2.0.0-alpha\'), \'2.0.0-beta\')\n\n    def test_max_all_invalid(self):\n        self.assertEqual(max_satisfying([\'v1\', \'1.2\', \'\'], \'*\'), None)\n\n    def test_max_invalid_range(self):\n        with self.assertRaises(ValueError):\n            max_satisfying([\'1.0.0\'], \'>>1\')\n\n\nif __name__ == "__main__":\n    unittest.main()\n'}

SKIP = {"tests", ".git", ".home", "__pycache__", "events.jsonl"}


def main():
    workspace = Path(sys.argv[1]) if len(sys.argv) > 1 else Path.cwd()
    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp) / "workspace"
        root.mkdir()
        for entry in workspace.iterdir():
            if entry.name in SKIP or entry.name.startswith(".") or entry.is_symlink():
                continue
            if entry.is_dir():
                shutil.copytree(entry, root / entry.name, symlinks=False,
                                ignore=shutil.ignore_patterns("__pycache__"))
            elif entry.is_file():
                shutil.copy2(entry, root / entry.name)
        for rel, text in TEST_FILES.items():
            target = root / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(text, encoding="utf-8")
        try:
            result = subprocess.run([sys.executable, "tests/run.py"], cwd=root, capture_output=True,
                                    text=True, timeout=90)
        except subprocess.TimeoutExpired:
            print("tests timed out")
            return 1
        output = result.stdout + result.stderr
        print(output[-4000:])
        return 0 if result.returncode == 0 else 1


if __name__ == "__main__":
    sys.exit(main())
